edges = [(0, 1), (0, 8), (1, 2), (2, 5), (3, 5), (3, 4), (4, 6), (6, 7), (7, 8)]

# Build adjacency
adj = {v: set() for v in range(9)}
for u, v in edges:
    adj[u].add(v)
    adj[v].add(u)

# Find shortest cycle using BFS
from collections import deque

def shortest_cycle(start):
    # BFS to find shortest cycle through start
    dist = {v: -1 for v in range(9)}
    parent = {v: -1 for v in range(9)}
    dist[start] = 0
    q = deque([start])
    while q:
        v = q.popleft()
        for nb in adj[v]:
            if dist[nb] == -1:
                dist[nb] = dist[v] + 1
                parent[nb] = v
                q.append(nb)
            elif nb != parent[v]:
                # Found a cycle
                return dist[v] + dist[nb] + 1
    return float('inf')

girth = min(shortest_cycle(v) for v in range(9))
print("Girth:", girth)

# Also verify degrees
deg = {v: 0 for v in range(9)}
for u, v in edges:
    deg[u] += 1
    deg[v] += 1
print("Degrees:", deg)
print("All degrees 2-5:", all(2 <= d <= 5 for d in deg.values()))
